// apps/agent-credential-mcp/src/tools/remove-agent-key.ts
function registerRemoveAgentKeyTool(server, kmsService) {
  server.registerTool(
    "remove-agent-key",
    {
      title: "Remove Agent Key",
      description: "Permanently deletes a locally stored agent keypair (agent ID). You CAN and MUST call this tool yourself whenever the user asks to delete, remove, reset or replace the agent identity - never tell the user you cannot delete it or that they must do it themselves. Ask the user to confirm first (deletion is irreversible), then call it once they say yes. did may be omitted only while exactly one agent identity exists; with several, omitting it is an error and nothing is removed. If removal fails because the OS keystore could not delete the encryption key, tell the user why and retry; only if it keeps failing, and the user agrees to leave the encryption key behind in the keystore, call again with force: true.",
      inputSchema: external_exports.object({
        did: external_exports.string().optional().describe("DID of the key to remove. Required when several identities exist."),
        force: external_exports.boolean().optional().describe(
          "Remove the identity even if its encryption key cannot be deleted from the OS keystore. Only after a normal removal failed and the user agreed."
        )
      }),
      annotations: {
        title: "Remove Agent Key",
        readOnlyHint: false,
        destructiveHint: true,
        idempotentHint: true,
        openWorldHint: false
      }
    },
    async ({ did, force }) => {
      if (!did && kmsService.list().length === 0) {
        return {
          content: [{ type: "text", text: "No agent identity found. Nothing to remove." }]
        };
      }
      let resolvedDid;
      try {
        resolvedDid = kmsService.resolveDid(did);
      } catch (error62) {
        return {
          content: [{ type: "text", text: error62 instanceof Error ? error62.message : String(error62) }],
          isError: true
        };
      }
      const record2 = kmsService.get(resolvedDid);
      if (!record2) {
        return {
          content: [
            { type: "text", text: `No key found for DID: ${resolvedDid}. Nothing to remove.` }
          ]
        };
      }
      try {
        const result = await kmsService.remove(resolvedDid, { force });
        if (!result.keystoreItemLeft) {
          return {
            content: [{ type: "text", text: `Removed key for DID: ${resolvedDid}` }]
          };
        }
        const osName = kmsService.osKeystoreName();
        const account = keychainAccountFor(AES_256_GCM, resolvedDid);
        return {
          content: [
            {
              type: "text",
              text: `Removed key for DID: ${resolvedDid}, but its encryption key could not be deleted from ${osName} (${result.reason}). The user can delete it by hand: service "${KEYCHAIN_SERVICE}", account "${account}".`
            }
          ]
        };
      } catch (error62) {
        return {
          content: [{ type: "text", text: error62 instanceof Error ? error62.message : String(error62) }],
          isError: true
        };
      }
    }
  );
}

