// apps/agent-credential-mcp/src/server.ts
var SERVER_INSTRUCTIONS = [
  `This server holds the agent identities (up to ${MAX_AGENT_IDENTITIES} ECDSA keys, one per agent)`,
  "used to sign payments. With more than one, pass `did` to every tool that acts on a single",
  "identity. Each private key is encrypted at rest; the AES key that encrypts it is kept in the",
  "OS keystore (macOS Keychain, Windows Credential Manager, Linux Secret Service) when one is",
  "usable, otherwise in a file beside the encrypted key, or in an operator-supplied environment",
  "variable.",
  "",
  "When the user asks where their key is stored, how safe it is, or whether the keychain /",
  "keystore setup worked, call `check-key-storage` and tell them its `summary` in plain",
  "language. It actually tests the stored key, so its answer is reliable. Do not guess from",
  "`keyManager`, and do not run shell or keychain commands (`security`, `secret-tool`, ...).",
  "",
  "If `remove-agent-key` fails because the OS keystore could not delete the encryption key,",
  "tell the user and retry. Offer `force: true` only if it keeps failing and the user agrees",
  "to leave the encryption key behind in the keystore.",
  "",
  "Never show private key material or the derived EVM address."
].join("\n");
function createServer(kmsService) {
  const server = new McpServer(
    {
      name: "agent-credential-mcp",
      version: "1.0.0"
    },
    { instructions: SERVER_INSTRUCTIONS }
  );
  registerCreateAgentDidTool(server, kmsService);
  registerSignEip712PayloadTool(server, kmsService);
  registerRemoveAgentKeyTool(server, kmsService);
  registerRenameAgentKeyTool(server, kmsService);
  registerListAgentKeysTool(server, kmsService);
  registerCheckKeyStorageTool(server, kmsService);
  return server;
}

// apps/agent-credential-mcp/src/shutdown.ts
var DEFAULT_CLOSE_TIMEOUT_MS = 1e3;
function createShutdown(deps) {
  let started = false;
  return async () => {
    if (started) return;
    started = true;
    const closeTimeoutMs = deps.closeTimeoutMs ?? DEFAULT_CLOSE_TIMEOUT_MS;
    let timer;
    const closed = deps.close().then(
      () => true,
      (error62) => {
        console.error(
          `Error while closing the server: ${error62 instanceof Error ? error62.message : String(error62)}`
        );
        return true;
      }
    );
    const gaveUp = new Promise((resolve) => {
      timer = setTimeout(() => resolve(false), closeTimeoutMs);
      timer.unref();
    });
    if (!await Promise.race([closed, gaveUp])) {
      console.error(`Closing the server took longer than ${closeTimeoutMs} ms; exiting anyway.`);
    }
    clearTimeout(timer);
    if (deps.hasPendingCall()) {
      deps.kill();
    } else {
      deps.exit(0);
    }
  };
}
function installShutdownHandlers(proc, deps) {
  const shutdown = createShutdown(deps);
  const run = () => void shutdown();
  proc.stdin.once("end", run);
  proc.stdin.once("close", run);
  proc.once("SIGINT", run);
  proc.once("SIGTERM", run);
  return shutdown;
}

// apps/agent-credential-mcp/src/run-stdio-server.ts
async function runStdioServer(kmsService) {
  const server = createServer(kmsService);
  const transport = new StdioServerTransport();
  await server.connect(transport);
  installShutdownHandlers(process, {
    close: () => server.close(),
    hasPendingCall: () => kmsService.hasPendingKeystoreCall(),
    exit: (code) => process.exit(code),
    kill: () => process.kill(process.pid, "SIGKILL")
  });
  console.error("server is listening on stdio");
}

